def autogenerated_cdd2_kernels():
    """
    Generates objects of type 'cuda_generator.CoalescedDdKernel2'.
    Duplicates are okay here (they'll be caught later, see 'duplicate_checker' above.)
    """

    # Throughout this function, we represent kernels by tuples
    #   (dtype, dd_rank, Wmax, Dcore, Dout, Tinner, subband_counts, et_levels)

    # Start with a few "baseline" kernels, so that unit tests can run even if all boolean flags are False.
    # The baseline kernels make a reasonable attempt to test a variety of code paths.
    # Note: we use dd_rank <= 5 here, since DedispersionConfig::make_random() uses default max_toplevel_rank=10.
    # FIXME: Wmax=32 is currently broken in "toy-size" kernels (it works in "production-size" kernels).
    
    kernels = [ 
        ('fp32', 4, 16, 8, 16, 1,   (2,2,1),   [0,1]),
        ('fp32', 5, 16, 8, 16, 1,   (2,2,1), [0,1,2]),
        ('fp16', 4,  8, 8,  8, 2, (2,3,1,1),   [0,1]),
        ('fp16', 5,  8, 8,  8, 2, (2,3,1,1), [0,1,2]),
        ('fp32', 6, 16, None, None, 2, (2,2,1), [0,1,2]),  # needed for configs/dedispersion/toy.yml
        ('fp32', 6,  8, None, None, 2, (2,2,1), [0,1,2]),  # needed for configs/dedispersion/toy.yml
        ('fp32', 6,  4, None, None, 2, (2,2,1), [0,1,2]),  # needed for configs/dedispersion/toy.yml
    ]

    if production_kernels:
        # Bare minimum kernels needed for configs/dedispersion/*.yml.
        # Also used in CoalescedDdKernel2::time(), so any changes made here should be reflected there.

        # triples = (dd_rank, subband_counts, et_levels)
        triples = [ 
            (7, (0,0,0,0,1), [0]),       # chime.yml
            (8, (0,0,0,0,1), [0]),       # chime.yml, chord_sb0.yml
            (7, (0,0,1,2,1), [0]),       # chime_sb1.yml
            (8, (0,0,1,2,1), [0]),       # chime_sb1.yml
            (7, (0,5,7,3,1), [0,1,2,3]), # chime_sb2.yml, chime_sb2_et.yml
            (8, (0,5,7,3,1), [0]),       # chime_sb2.yml, chime_sb2_et.yml
            (8, (1,2,2,2,1), [0]),       # chord_sb1.yml
            (8, (5,9,7,3,1), [0,1,2,3])  # chord_sb2.yml, chord_sb2_et.yml
        ]
        
        for dd_rank, subband_counts, et_levels in triples:
            # Values common to all chime/chord kernels.
            for Wmax in [32,16,8,4]:
                dtype, Dcore, Dout, Tinner = ('fp16', None, None, 1)
                kernels += [ (dtype, dd_rank, Wmax, Dcore, Dout, Tinner, subband_counts, et_levels) ]

        # The production configs above are all float16, but CoalescedDdKernel2::time_selected()
        # also times float32, via DedispersionConfig::make_mini_chord(float32). That config has
        # toplevel_tree_rank=16 (hence dd_rank=8) and max_width=16 in every primary tree, so
        # (dd_rank=8, Wmax=16) covers every float32 kernel it needs. Without these, the float32
        # half of 'pirate_frb time --cdd2' prints "no cdd2 kernel in this build" and is skipped.
        # Each costs ~14 sec of compile time, so this is cheap; delete the loop if that changes.

        for dd_rank, subband_counts, et_levels in triples:
            if dd_rank == 8:
                kernels += [ ('fp32', dd_rank, 16, None, None, 1, subband_counts, [0]) ]

    if debug_cdd2_kernels or debug_gpu_dd:
        # Add some randomly generated kernels.
        # python -m pirate_frb random_kernels --cdd2

        kernels += [
            # (dtype, dd_rank, Wmax, Dcore, Dout, Tinner, subband_counts, et_levels)
            ('fp16', 3, 1, 4, 16, 4, (10, 6, 3, 0, 1), [0]),
            ('fp16', 4, 1, 4, 16, 4, (10, 6, 3, 0, 1), [0]),     # continuation
            ('fp16', 5, 8, 8, 16, 4, (10, 13, 6, 2, 1), [0]),
            ('fp16', 6, 8, 8, 16, 4, (10, 13, 6, 2, 1), [0, 2, 1, 3]),     # continuation
            ('fp16', 4, 8, 4, 4, 1, (0, 1, 1), [0, 1]),
            ('fp16', 5, 8, 4, 4, 1, (0, 1, 1), [0]),     # continuation
            ('fp16', 3, 2, 4, 16, 1, (0, 1), [0]),
            ('fp16', 7, 16, 8, 16, 4, (6, 14, 2, 0, 1), [0]),
            ('fp16', 8, 16, 8, 16, 4, (6, 14, 2, 0, 1), [0, 4, 3, 2, 5, 1]),     # continuation
            ('fp32', 4, 1, 4, 8, 2, (6, 0, 0, 1), [0]),
            ('fp32', 5, 1, 4, 8, 2, (6, 0, 0, 1), [0]),     # continuation
            ('fp32', 5, 1, 2, 8, 2, (8, 12, 2, 0, 1), [0, 2, 1]),
            ('fp32', 6, 1, 2, 8, 2, (8, 12, 2, 0, 1), [0, 1, 3]),     # continuation
        ]


    for dtype, dd_rank0, Wmax, Dcore0, Dout0, Tinner, subband_counts, et_levels in kernels:
        for et_level in et_levels:
            dd_rank = dd_rank0 - et_level
            pf_rank = (dd_rank+1) // 2
            Dout = Dout0 if (Dout0 is not None) else 2**pf_rank
            Dcore = Dcore0 if (Dcore0 is not None) else min(Dout,8)

            sbc = cuda_generator.FrequencySubbands.restrict_subband_counts(subband_counts, et_level, pf_rank)
            fs = cuda_generator.FrequencySubbands(subband_counts = sbc)
            cdd2 = cuda_generator.CoalescedDdKernel2(dtype, dd_rank, fs, Wmax, Dcore, Dout, Tinner)
            yield cdd2


def autogenerated_sbdd_kernels():
    """
    Generates objects of type 'cuda_generator.SbDedisperser'.
    Duplicates are okay here (they'll be caught later, see 'duplicate_checker' above.)
    """

    # One sbdd kernel per cdd2 kernel, so that sbdd coverage automatically tracks cdd2
    # coverage (and the two lists can't drift). The correspondence is total, since
    # CoalescedDdKernel2 asserts (frequency_subbands.pf_rank == dd.rank1) and (dd_rank >= 3),
    # which are exactly the constraints SbDedisperser needs.
    #
    # Note that the sbdd registry key is only (dd_rank, subband_counts) -- no dtype, Wmax,
    # Dcore, Dout or Tinner -- so the float16 and float32 cdd2 variants of a tree, and all
    # of its Wmax values, collapse onto a single sbdd kernel. Currently this yields 80
    # objects, which dedupe to 23 distinct kernels.
    #
    # (There is deliberately no 'debug_sbdd_kernels' flag: debug_cdd2_kernels already
    # widens both. If sbdd-only kernels are ever wanted -- e.g. to iterate on sbdd without
    # paying for the much more expensive cdd2 compiles -- add a second loop here.)

    for cdd2 in autogenerated_cdd2_kernels():
        yield cuda_generator.SbDedisperser(cdd2.dd_rank, cdd2.frequency_subbands)

    # The second loop anticipated above: sbdd kernels with no cdd2 counterpart.
    if varmap_kernels:
        for sbdd in varmap_sbdd_kernels():
            yield sbdd


def varmap_sbdd_kernels():
    """
    Generates objects of type 'cuda_generator.SbDedisperser', for 'pirate_frb variance_map'.

    Duplicates (with each other, or with autogenerated_sbdd_kernels()) are okay here.
    """

    # The variance map A (notes/variance_map.tex, section "The variance map") is computed
    # by sweeping one-hot inputs through the dedispersion stages. That needs an sbdd kernel for
    # the config's (dd_rank, subband_counts), and nothing else -- in particular no cdd2 kernel,
    # which is why this list can be much wider than the one in autogenerated_cdd2_kernels()
    # without a comparable compile-time cost.
    #
    # Coverage is a small ladder in "how subbanded" the tree is, at every dd_rank that
    # 'variance_map' can be pointed at. Absent this, the tool silently falls back to its CPU
    # sweep, which is ~60x slower (13 s vs 0.2 s at tree rank 10, 400 channels) and becomes
    # hours at production rank -- so a missing kernel does not fail loudly, it just makes a
    # region of parameter space too slow to explore.
    #
    # dd_rank 3..8 covers tree rank 5..16 (dd_rank = ceil(r/2) with no early trigger), i.e.
    # subscale through CHIME (r=15) and CHORD (r=16).

    for dd_rank in range(3, 9):
        # SbDedisperser requires len(subband_counts) == pf_rank+1, and the last entry to be 1.
        pf_rank = (dd_rank+1) // 2

        # The ladder, in units of "levels below pf_rank that carry subbands". Entry 0 is the
        # no-subband case N=1 (M = 2^pf_rank), which is the one 'variance_map' uses most --
        # the variance map tex notes' first milestone is stated for a single unsubbanded tree. The rest
        # bracket the shipped configs: at pf_rank=4 they are N = 1, 2, 5, 9 against N = 3 for
        # chime_sb1, 16 for chime_sb2 and 25 for chord_sb2.
        shapes = [ [0]*pf_rank + [1] ]

        if pf_rank >= 1:
            shapes += [ [0]*(pf_rank-1) + [1,1] ]
        if pf_rank >= 2:
            shapes += [ [0]*(pf_rank-2) + [2,2,1] ]
        if pf_rank >= 3:
            shapes += [ [0]*(pf_rank-3) + [3,3,2,1] ]

        for subband_counts in shapes:
            fs = cuda_generator.FrequencySubbands(subband_counts = subband_counts)
            yield cuda_generator.SbDedisperser(dd_rank, fs)

    # The shipped CHIME/CHORD subband shapes, so that 'variance_map' can be run on
    # configs/dedispersion/*.yml regardless of whether production_kernels is set. These are
    # duplicates when production_kernels=True, which is harmless.
    #
    # Kept in sync with the 'triples' list in autogenerated_cdd2_kernels(): if a shape is
    # added there, add it here too, or variance_map will not run on the config that needs it.

    for subband_counts in [ (0,0,0,0,1), (0,0,1,2,1), (0,5,7,3,1), (5,9,7,3,1) ]:
        for dd_rank in [7, 8]:
            fs = cuda_generator.FrequencySubbands(subband_counts = subband_counts)
            yield cuda_generator.SbDedisperser(dd_rank, fs)


def autogenerated_pf_weight_reader_kernels():
    """
    Generates objects of type 'cuda_generator.PfWeightReader'.
    Duplicates are okay here (they'll be caught later, see 'duplicate_checker' above.)
    """

    if not debug_pfwr_kernels:
        return
    
    # Add some randomly generated kernels.
    # python -m pirate_frb random_kernels --pfwr

    # (dtype, subband_counts, Dcore, P, Tinner)
    kernels = [
        ('fp32', (2,1,1), 1, 14, 16),
        ('fp16', (7,6,2,1), 8, 10, 2),
        ('fp32', (0,2,1), 1, 1, 4),
        ('fp16', (4,0,1,1), 2, 5, 1),
        ('fp32', (3,2,1), 1, 5, 32),
        ('fp16', (14,4,4,0,1), 8, 3, 2),
        ('fp16', (13,7,3,0,1), 4, 3, 4),
        ('fp16', (3,2,1), 2, 7, 32),
        ('fp32', (6,5,1,1,1), 4, 2, 4),
        ('fp32', (4,3,1,1), 2, 2, 8),
        ('fp32', (3,2,1), 8, 5, 4),
        ('fp16', (1,1,1), 4, 2, 1),
        ('fp32', (9,4,0,2,1), 16, 8, 1),
        ('fp32', (0,2,1), 1, 8, 2),
        ('fp32', (3,0,1), 1, 6, 1)
    ]

    for (dtype, subband_counts, Dcore, P, Tinner) in kernels:
        fs = cuda_generator.FrequencySubbands(subband_counts = subband_counts)
        yield cuda_generator.PfWeightReader(fs, dtype, Dcore, P, Tinner)


def autogenerated_pf_output_kernels():
    """
    Generates objects of type 'cuda_generator.PfOutput'.
    Duplicates are okay here (they'll be caught later, see 'duplicate_checker' above.)
    """

    # In this case, we can enumerate all valid parameter choices
    # (i.e. no need to randomly generate kernels).

    if not debug_pfo_kernels:
        return
    
    for (dtype,Lmin) in [ ('float',0), ('__half',1) ]:
        for L in range(Lmin, 6):
            yield cuda_generator.PfOutput(dtype, Dout=2**L)


####################################################################################################


if __name__ == '__main__':
    main()
